import{_ as a,o as e,c as i,a2 as l}from"./chunks/framework.DnrXFDHb.js";const r="/images/screenshots/register-account.png",o="/images/screenshots/login-account.png",m=JSON.parse('{"title":"注册 / 登录","description":"完成账号注册和登录，确认可以进入控制台并继续创建 API Key。","frontmatter":{"title":"注册 / 登录","description":"完成账号注册和登录，确认可以进入控制台并继续创建 API Key。"},"headers":[],"relativePath":"guide/register.md","filePath":"guide/register.md","lastUpdated":1783061751000}'),d={name:"guide/register.md"};function s(n,t,c,h,p,u){return e(),i("div",null,[...t[0]||(t[0]=[l('<h1 id="注册-登录" tabindex="-1">注册 / 登录 <a class="header-anchor" href="#注册-登录" aria-label="Permalink to &quot;注册 / 登录&quot;">​</a></h1><p>这一页教你注册账号。注册好、能登录进控制台（管理账号的网页后台），就算完成了。目前只支持用账号密码注册登录。</p><p>打开<strong>你的中转站网址</strong>。中转站就是你用来登录、充值、创建 Key 的网站。</p><p><img src="'+r+'" alt="注册页" loading="lazy"></p><h2 id="注册" tabindex="-1">注册 <a class="header-anchor" href="#注册" aria-label="Permalink to &quot;注册&quot;">​</a></h2><ol><li>打开你的中转站网址。</li><li>点右上角的「注册」或「开始使用」。</li><li>按页面提示填账号和密码。</li><li>再输一遍密码。</li><li>点「创建账户」。</li></ol><h2 id="登录" tabindex="-1">登录 <a class="header-anchor" href="#登录" aria-label="Permalink to &quot;登录&quot;">​</a></h2><p>注册完成后，回到登录页：</p><p><img src="'+o+'" alt="登录页" loading="lazy"></p><ol><li>打开登录页。</li><li>输入用户名或邮箱。</li><li>输入密码。</li><li>点「登录」，进入控制台。</li></ol><h2 id="开始前准备" tabindex="-1">开始前准备 <a class="header-anchor" href="#开始前准备" aria-label="Permalink to &quot;开始前准备&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>账号和密码</td><td>以后登录都要用，记下来、收好</td></tr><tr><td>浏览器</td><td>推荐用 Chrome、Edge、Safari 的最新版本</td></tr><tr><td>网络环境</td><td>页面一直打不开的话，先看看网络正不正常</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">提示</p><p>如果页面提示要邀请码或人工审核，按页面说明提交申请，或者通过中转站的售后入口问一下开通方式。</p></div><h2 id="注册好了怎么确认" tabindex="-1">注册好了怎么确认 <a class="header-anchor" href="#注册好了怎么确认" aria-label="Permalink to &quot;注册好了怎么确认&quot;">​</a></h2><ul><li>能进控制台。</li><li>能看到余额或套餐状态。</li><li>能进 API Key 管理页面。</li><li>能找到帮助入口或售后联系方式。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>注册完、能登录了，接着去 <a href="/guide/recharge">充值 / 续费</a>。</p>',17)])])}const g=a(d,[["render",s]]);export{m as __pageData,g as default};
